create or replace function public.schoolpro_member_can_manage(p_school uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','it_admin')) or exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=auth.uid())$$;revoke all on function public.schoolpro_member_can_manage(uuid) from public,anon;grant execute on function public.schoolpro_member_can_manage(uuid) to authenticated;